package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService; import EmployeeManagementSystem.entity.EmployeeSeparation; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.service.EmployeeSeparationService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/separations") public class EmployeeSeparationController{
 private final RequestScopeService scope;private final EmployeeSeparationService s;private final JwtUtil j;public EmployeeSeparationController(EmployeeSeparationService s,JwtUtil j,RequestScopeService requestScope){this.scope=requestScope;this.s=s;this.j=j;}private String token(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);}private String u(String a){return j.extractUsername(token(a));}private String r(String a){String x=j.extractRole(token(a));return x==null?"":x.replace("ROLE_","").toUpperCase();}private boolean m(String x){return Set.of("ADMIN","HR","MANAGER").contains(x);}private RuntimeException bad(Exception e){return new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}
@GetMapping("/my") public List<EmployeeSeparation> my(@RequestHeader("Authorization")String a){return s.list(u(a),false);}
@GetMapping public List<EmployeeSeparation> list(@RequestHeader("Authorization")String a){return m(r(a))?scope.visibleTo(r(a),u(a),s.list(u(a),true)):s.list(u(a),false);}
@PostMapping public EmployeeSeparation create(@RequestHeader("Authorization")String a,@RequestBody EmployeeSeparation x){try{return s.create(x,u(a));}catch(Exception e){throw bad(e);}}@PutMapping("/{id}") public EmployeeSeparation update(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody EmployeeSeparation x){scope.assertCanAccessById(r(a),u(a),s.list(u(a),true),id);try{return s.update(id,x,u(a),!u(a).equals(scope.ownerUserId(s.list(u(a),true).stream().filter(v->Objects.equals(v.getId(),id)).findFirst().orElse(null))));}catch(Exception e){throw bad(e);}}@PatchMapping("/{id}/review") public EmployeeSeparation review(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){scope.assertCanReviewById(r(a),u(a),s.list(u(a),true),id);if(!m(r(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{EmployeeSeparation p=new EmployeeSeparation();p.setManagerCleared((Boolean)b.getOrDefault("managerCleared",false));p.setHrCleared((Boolean)b.getOrDefault("hrCleared",false));p.setFinanceCleared((Boolean)b.getOrDefault("financeCleared",false));p.setAssetCleared((Boolean)b.getOrDefault("assetCleared",false));p.setAccessCleared((Boolean)b.getOrDefault("accessCleared",false));p.setExitInterviewNotes((String)b.get("exitInterviewNotes"));return s.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("hrComment","")),p,u(a));}catch(Exception e){throw bad(e);}}}
